  cover_image = EXCLUDED.cover_image,
  published_at = EXCLUDED.published_at;

-- Post 19: Niche - Gifts for coffee snobs
INSERT INTO blog_posts (title, slug, excerpt, cover_image, author, tags, published, published_at, seo_title, seo_description, seo_keywords, content)
VALUES (
  'Gifts for Coffee Snobs: What Serious Coffee Lovers Actually Want',
  'gifts-for-coffee-snobs',
  'Shopping for someone who takes their coffee seriously? These gifts will impress even the most discerning caffeine connoisseur.',
  'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=1200&q=80',
  'The Gifted Team',
  ARRAY['Gift Ideas', 'Food & Drink', 'Hobbies'],
  true,
  NOW() + INTERVAL '19 days',
  'Best Gifts for Coffee Lovers 2026 | Coffee Snob Gift Ideas',
  'Find perfect gifts for coffee snobs. From premium beans to professional equipment, impress the serious coffee lover in your life.',
  ARRAY['gifts for coffee lovers', 'coffee snob gifts', 'barista gifts', 'coffee equipment', 'specialty coffee gifts'],
  E'Coffee snobs are particular. They''ve moved beyond instant coffee, past pod machines, and into the world of single-origin beans, precise brewing ratios, and heated debates about extraction times.\n\nThe good news? They''re always looking to upgrade their setup. Here''s what they actually want.\n\n## Premium Beans\n\n### Specialty Coffee Subscription\n\n[Pact Coffee](https://www.pactcoffee.com), [Square Mile](https://shop.squaremilecoffee.com), or [Hasbean](https://www.hasbean.co.uk) deliver freshly roasted, specialty-grade beans. A subscription means they never run out.\n\n**Price:** £8-15/bag, subscriptions from £25/month\n\n### Single Origin Selection\n\nA curated selection of single-origin beans from different regions. [Origin Coffee](https://www.origincoffee.co.uk) or [Workshop Coffee](https://www.workshopcoffee.com) offer excellent variety packs.\n\n**Price:** £30-50\n\n![Specialty coffee beans](https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=800&q=80)\n\n### Rare or Experimental Coffee\n\n[Kopi](https://www.kopi.coffee) specialises in rare, competition-grade coffees. Expensive but extraordinary for true enthusiasts.\n\n**Price:** £20-50 per bag\n\n## Brewing Equipment\n\n### Precision Grinder\n\nA quality burr grinder is essential. The [Baratza Encore](https://www.baratza.com) is the entry point for serious coffee. [Comandante](https://www.comandantegrinder.com) or [1Zpresso](https://1zpresso.coffee) for hand grinders.\n\n**Price:** £100-300\n\n### Pour-Over Setup\n\nA [Chemex](https://www.chemexcoffeemaker.com), [Hario V60](https://www.hario.co.uk), or [Kalita Wave](https://www.kalita.co.jp) for pour-over brewing. Include filters and a gooseneck kettle for the complete setup.\n\n**Price:** £30-80\n\n### AeroPress\n\nThe [AeroPress](https://aeropress.com) is beloved by coffee nerds for its versatility and portability. If they don''t have one, they want one.\n\n**Price:** £30-35\n\n### Gooseneck Kettle\n\nPrecise pouring requires a gooseneck kettle. [Fellow Stagg EKG](https://fellowproducts.com) is the gold standard—temperature control, beautiful design, and precise pour.\n\n**Price:** £100-150\n\n![Pour over coffee setup](https://images.unsplash.com/photo-1517701550927-30cf4ba1dba5?w=800&q=80)\n\n### Coffee Scale\n\nPrecision matters. The [Acaia Pearl](https://acaia.co) is the professional choice, but [Hario](https://www.hario.co.uk) and [Timemore](https://www.timemore.com) offer excellent budget options with timers.\n\n**Price:** £30-200\n\n## Espresso Upgrades\n\n### Bottomless Portafilter\n\nA naked portafilter for their espresso machine lets them see (and improve) their extraction. Satisfying to use and educational.\n\n**Price:** £30-60\n\n### Precision Tamper\n\nA quality tamper like [Pullman](https://pullman.coffee) or [Decent](https://decentespresso.com) ensures consistent pressure. Levelling tampers are particularly useful.\n\n**Price:** £50-150\n\n### WDT Tool\n\nA Weiss Distribution Technique tool for breaking up clumps in espresso grounds. Small but makes a real difference.\n\n**Price:** £15-40\n\n### Espresso Cups\n\nBeautiful espresso cups from [notNeutral](https://www.notneutral.com), [Acme](https://www.acmecups.com), or [Loveramics](https://www.loveramics.com). Proper cups for proper coffee.\n\n**Price:** £20-40\n\n## Accessories\n\n### Coffee Storage\n\nAirtight containers that preserve freshness. [Fellow Atmos](https://fellowproducts.com) or [Airscape](https://planetarydesign.com) vacuum canisters.\n\n**Price:** £25-40\n\n### Milk Pitcher\n\nFor latte art practice. [Rhinowares](https://www.rhinowares.com) or [Motta](https://www.mikibar.it) are professional standards.\n\n**Price:** £15-30\n\n### Knock Box\n\nFor espresso makers—a proper knock box for spent grounds. [Dreamfarm Grindenstein](https://www.dreamfarm.com) is compact and effective.\n\n**Price:** £25-40\n\n## Experiences\n\n### Barista Course\n\nA course at [London School of Coffee](https://www.londonschoolofcoffee.com), [Prufrock](https://www.prufrockcoffee.com), or their local specialty roaster. Learn from professionals.\n\n**Price:** £100-300\n\n### Roastery Tour\n\nA tour of a local roastery to see how beans go from green to roasted. Many specialty roasters offer tours.\n\n**Price:** £20-50\n\n### Coffee Tasting\n\nA cupping session at [Square Mile](https://shop.squaremilecoffee.com), [Origin](https://www.origincoffee.co.uk), or similar. Learn to taste coffee like a professional.\n\n**Price:** £20-40\n\n## Books & Learning\n\n### The World Atlas of Coffee by James Hoffmann\n\nThe definitive guide to coffee origins, processing, and brewing. Essential reading for any coffee enthusiast.\n\n**Price:** £25\n\n### Coffee Subscription + Education\n\n[James Hoffmann''s YouTube channel](https://www.youtube.com/channel/UCMb0O2CdPBNi-QqPk5T3gsQ) is free, but pair beans with his videos for a learning experience.\n\n**Price:** Free + beans\n\n## What to Avoid\n\n- Pod machines or capsules (they''ve moved past these)\n- Flavoured coffee (purists generally avoid it)\n- Pre-ground coffee (freshness matters)\n- Cheap blade grinders (they destroy beans)\n- Novelty mugs (they have opinions about cups)\n\n## The Safe Bet\n\nWhen in doubt, a gift card to their favourite roaster or [Has Bean](https://www.hasbean.co.uk) lets them choose exactly what they want.\n\n---\n\n*Looking for more gift inspiration? [Join the Gifted waitlist](/#signup) and discover personalised recommendations for everyone on your list.*'
)
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  excerpt = EXCLUDED.excerpt,
  cover_image = EXCLUDED.cover_image,
  published_at = EXCLUDED.published_at;

-- Post 20: Niche - Gifts for long distance relationships
INSERT INTO blog_posts (title, slug, excerpt, cover_image, author, tags, published, published_at, seo_title, seo_description, seo_keywords, content)
VALUES (
  'Long Distance Relationship Gifts: Staying Connected Across Miles',
  'long-distance-relationship-gifts',
  'Miles apart but still close at heart? These thoughtful gifts help couples stay connected when they can''t be together.',
  'https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?w=1200&q=80',
  'The Gifted Team',
  ARRAY['Gift Ideas', 'Relationships', 'Couples'],
  true,
  NOW() + INTERVAL '20 days',
  'Best Long Distance Relationship Gifts 2026 | LDR Gift Ideas',
  'Find perfect gifts for long distance relationships. Thoughtful presents that help couples stay connected across the miles.',
  ARRAY['long distance relationship gifts', 'LDR gifts', 'gifts for couples apart', 'distance relationship presents', 'gifts for boyfriend abroad'],
  E'Long distance relationships are hard. The miles between you can feel insurmountable, especially on difficult days. The right gift can bridge that gap—not by pretending the distance doesn''t exist, but by acknowledging it and finding ways to feel closer despite it.\n\nHere are gifts that help couples stay connected.\n\n## Touch & Connection\n\n### Long Distance Touch Bracelets\n\n[Bond Touch](https://www.bond-touch.com) or [HEY](https://www.heybracelet.com) bracelets let you send a touch to your partner''s wrist from anywhere in the world. When you tap yours, theirs vibrates. Simple but meaningful.\n\n**Price:** £80-120 per pair\n\n### Long Distance Lamps\n\n[Friendship Lamps](https://www.friendlamps.com) or [Filimin](https://filimin.com) light up when touched—touch yours and theirs lights up too, no matter where they are. A gentle way to say "thinking of you."\n\n**Price:** £100-200 per pair\n\n![Connected couple](https://images.unsplash.com/photo-1522098543979-ffc7f79a56c4?w=800&q=80)\n\n### Pillow With Their Voice\n\nRecord a message that plays when hugged. [Recordable Pillow](https://www.amazon.co.uk) options exist, or DIY with a recordable sound module.\n\n**Price:** £20-40\n\n### Their Perfume/Cologne\n\nWearing their scent is surprisingly comforting. Get a bottle of whatever they wear so you can smell them when you miss them.\n\n**Price:** £40-100\n\n## Shared Experiences\n\n### Watch Party Subscription\n\n[Netflix](https://www.netflix.com), [Disney+](https://www.disneyplus.com), or [Amazon Prime](https://www.amazon.co.uk/prime) with [Teleparty](https://www.teleparty.com) extension lets you watch together in sync while chatting.\n\n**Price:** £10-15/month\n\n### Online Cooking Class Together\n\nBook the same virtual cooking class and cook together over video call. [Airbnb Experiences](https://www.airbnb.co.uk/s/experiences/online) offers many options.\n\n**Price:** £20-50\n\n### Same Book, Same Time\n\nBuy two copies of the same book and read it together, discussing as you go. Creates shared experience and conversation.\n\n**Price:** £20-30\n\n### Subscription Box for Two\n\nMatching subscription boxes—coffee, snacks, or wine—so you''re experiencing the same things apart.\n\n**Price:** £30-60/month\n\n## Countdown & Planning\n\n### Countdown Clock\n\nA digital countdown to your next visit. [Amazon](https://www.amazon.co.uk) has various countdown clocks, or use an app like [Countdown Widget](https://apps.apple.com).\n\n**Price:** £15-30\n\n### Scratch-Off Map\n\nA map where you scratch off places you''ve visited together—and plan where to go next. [Luckies](https://www.luckies.co.uk) makes beautiful versions.\n\n**Price:** £20-30\n\n### Travel Fund Jar\n\nA jar or savings pot specifically for visits. Make it visual and satisfying to contribute to.\n\n**Price:** £10-20\n\n![Planning future visits](https://images.unsplash.com/photo-1488646953014-85cb44e25828?w=800&q=80)\n\n## Sentimental Keepsakes\n\n### Photo Book of Your Relationship\n\nA [Photobox](https://www.photobox.co.uk) or [CEWE](https://www.cewe.co.uk) book documenting your time together. Something physical to hold when you miss them.\n\n**Price:** £25-50\n\n### Coordinates Jewellery\n\nA necklace or bracelet with the coordinates of where you met, or where they are. [Etsy](https://www.etsy.com) has many options.\n\n**Price:** £30-80\n\n### Open When Letters\n\nA set of letters to open at specific times: "Open when you miss me," "Open when you need a laugh," "Open when you can''t sleep." Requires effort but means everything.\n\n**Price:** Minimal (maximum effort)\n\n### Star Map of Special Date\n\nA print showing the night sky on the day you met, or your anniversary. [Under Lucky Stars](https://www.underluckystars.com) creates beautiful versions.\n\n**Price:** £40-80\n\n## Practical Connection\n\n### Good Webcam\n\nVideo calls are your lifeline. A quality webcam like [Logitech Brio](https://www.logitech.com) or [Elgato Facecam](https://www.elgato.com) makes calls feel more present.\n\n**Price:** £100-200\n\n### Ring Light\n\nGood lighting improves video calls dramatically. A simple ring light means they can actually see your face properly.\n\n**Price:** £20-40\n\n### Comfortable Headphones\n\nFor long calls, comfortable headphones matter. [Sony WH-1000XM5](https://www.sony.co.uk) or [Bose](https://www.bose.co.uk) for quality and comfort.\n\n**Price:** £250-350\n\n## Care Packages\n\n### Snacks From Your Location\n\nSend local snacks, treats, or specialties from where you are. A taste of your world.\n\n**Price:** £20-40\n\n### Comfort Package\n\nYour hoodie (that smells like you), their favourite treats, a handwritten letter, and something soft to hug.\n\n**Price:** £30-60\n\n### Date Night Box\n\nEverything needed for a virtual date: same wine, same snacks, same candle. Open together over video call.\n\n**Price:** £40-80\n\n## What to Avoid\n\n- Gifts that emphasise the distance negatively\n- Anything that requires them to be with you to use\n- Promises you can''t keep\n- Generic "I miss you" items without personal meaning\n\n## The Most Important Gift\n\nConsistency. Regular calls, good morning texts, and showing up even when it''s hard. Physical gifts matter, but presence—even virtual presence—matters more.\n\n---\n\n*Looking for more gift inspiration? [Join the Gifted waitlist](/#signup) and discover personalised recommendations for everyone on your list.*'
)
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  excerpt = EXCLUDED.excerpt,
  cover_image = EXCLUDED.cover_image,
  published_at = EXCLUDED.published_at;

-- Post 21: Niche - Gifts for gamers
INSERT INTO blog_posts (title, slug, excerpt, cover_image, author, tags, published, published_at, seo_title, seo_description, seo_keywords, content)
VALUES (
  'Gifts for Gamers: What They Actually Want (Not Another Gift Card)',
  'gifts-for-gamers',
  'Shopping for a gamer? These gifts enhance their setup, comfort, and gaming experience—without guessing which games they want.',
  'https://images.unsplash.com/photo-1538481199705-c710c4e965fc?w=1200&q=80',
  'The Gifted Team',
  ARRAY['Gift Ideas', 'Gaming', 'Tech'],
  true,
  NOW() + INTERVAL '21 days',
  'Best Gifts for Gamers 2026 | Gaming Gift Ideas',
  'Find perfect gifts for gamers. From peripherals to comfort items, these presents enhance their gaming without guessing which games they want.',
  ARRAY['gifts for gamers', 'gaming gifts', 'gamer presents', 'video game gifts', 'PC gaming gifts'],
  E'Gamers are tricky to buy for. They know exactly which games they want, have strong opinions about peripherals, and their setup is deeply personal. Buying the wrong thing means it''ll sit unused.\n\nThe solution? Focus on comfort, quality-of-life improvements, and accessories rather than games themselves.\n\n## Comfort & Ergonomics\n\n### Gaming Chair Upgrade\n\nNot a racing-style chair—a proper ergonomic chair. [Secretlab](https://secretlab.co.uk), [Herman Miller x Logitech](https://store.hermanmiller.com), or [Autonomous](https://www.autonomous.ai) make chairs designed for long sessions.\n\n**Price:** £300-1500\n\n### Lumbar Support Pillow\n\nIf a new chair isn''t in budget, a quality lumbar pillow from [Purple](https://purple.com) or [Cushion Lab](https://cushionlab.com) improves any chair.\n\n**Price:** £40-80\n\n![Gaming setup](https://images.unsplash.com/photo-1593305841991-05c297ba4575?w=800&q=80)\n\n### Wrist Rest\n\nA quality wrist rest for keyboard and mouse. [Glorious](https://www.gloriousgaming.com) and [HyperX](https://hyperx.com) make popular options.\n\n**Price:** £15-30\n\n### Blue Light Glasses\n\nGaming glasses from [Gunnar](https://gunnar.com) or [HyperX](https://hyperx.com) reduce eye strain during long sessions.\n\n**Price:** £40-80\n\n## Audio\n\n### Quality Headset\n\nA proper gaming headset makes a huge difference. [SteelSeries Arctis](https://steelseries.com), [HyperX Cloud](https://hyperx.com), or [Audeze Maxwell](https://www.audeze.com) for premium.\n\n**Price:** £80-400\n\n### Headphone Stand\n\nA proper stand keeps headphones safe and looks good. [Corsair](https://www.corsair.com), [Razer](https://www.razer.com), or wooden options from [Etsy](https://www.etsy.com).\n\n**Price:** £20-50\n\n### Desktop Speakers\n\nFor when they''re not using headphones. [Audioengine A2+](https://audioengineusa.com) or [Edifier](https://www.edifier.com) offer excellent desktop speakers.\n\n**Price:** £150-300\n\n## Desk Setup\n\n### Monitor Light Bar\n\nThe [BenQ ScreenBar](https://www.benq.eu) illuminates the desk without screen glare. Essential for eye comfort during evening sessions.\n\n**Price:** £100-130\n\n### Cable Management\n\nCable raceways, velcro ties, and under-desk trays transform a messy setup. [D-Line](https://www.d-line.com) makes good cable management solutions.\n\n**Price:** £20-50\n\n### Desk Mat\n\nA large desk mat from [Grovemade](https://grovemade.com), [Orbitkey](https://www.orbitkey.com), or gaming brands provides a clean surface for mouse and keyboard.\n\n**Price:** £30-80\n\n### LED Strip Lights\n\n[Philips Hue](https://www.philips-hue.com) or [Govee](https://www.govee.com) LED strips for ambient lighting. Many sync with games for immersive effects.\n\n**Price:** £30-100\n\n![RGB gaming setup](https://images.unsplash.com/photo-1616588589676-62b3bd4ff6d2?w=800&q=80)\n\n## Peripherals\n\n### Quality Mouse Pad\n\nA proper gaming mousepad from [Artisan](https://www.artisan-jp.com), [Zowie](https://zowie.benq.eu), or [SteelSeries](https://steelseries.com). Size and surface matter for their playstyle.\n\n**Price:** £30-60\n\n### Controller Stand\n\nA charging stand for controllers keeps them organised and ready. Official stands from [PlayStation](https://www.playstation.com) or [Xbox](https://www.xbox.com), or third-party options.\n\n**Price:** £20-40\n\n### Keycaps\n\nCustom keycaps for mechanical keyboards. [Drop](https://drop.com) and [KBDfans](https://kbdfans.com) offer beautiful sets. Check their keyboard compatibility first.\n\n**Price:** £50-150\n\n## Sustenance\n\n### Gaming Snack Subscription\n\n[Graze](https://www.graze.com), [MunchPak](https://www.munchpak.com), or Japanese snack boxes for gaming fuel that doesn''t leave greasy fingers.\n\n**Price:** £15-30/month\n\n### Quality Water Bottle\n\nHydration matters. A [Chilly''s](https://www.chillys.com) or [Hydro Flask](https://www.hydroflask.com) keeps water cold through long sessions.\n\n**Price:** £25-40\n\n### Coffee/Energy Setup\n\nA quality coffee maker or their preferred energy drinks. Gamers run on caffeine.\n\n**Price:** £30-100\n\n## Collectibles & Decor\n\n### Game Art Prints\n\n[Cook & Becker](https://www.cookandbecker.com) sells official game art prints. Beautiful, frameable art from games they love.\n\n**Price:** £40-200\n\n### Figures & Statues\n\nOfficial figures from [First 4 Figures](https://www.first4figures.com), [Good Smile Company](https://www.goodsmile.info), or game-specific merchandise.\n\n**Price:** £30-500\n\n### Artbook\n\nThe art book for their favourite game. Most major releases have beautiful hardcover art books.\n\n**Price:** £30-50\n\n## What to Avoid\n\n- Games (they know what they want)\n- Cheap peripherals (they''ll replace them)\n- "Gamer" branded junk food\n- Anything that assumes their taste\n\n## The Safe Bet\n\nGift cards to [Steam](https://store.steampowered.com), [PlayStation Store](https://store.playstation.com), [Xbox](https://www.xbox.com), or [Nintendo eShop](https://www.nintendo.co.uk) let them choose. Not exciting, but always appreciated.\n\n---\n\n*Looking for more gift inspiration? [Join the Gifted waitlist](/#signup) and discover personalised recommendations for everyone on your list.*'
)
